USING DUAL ON (T.SQL_ID = 'APPLICATION' AND T.MDU_DIVS_CD = 'DM')
WHEN MATCHED THEN UPDATE SET T.SQL_NM = '[B] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''APPLICATION''', T.SQL_DTL_CTN = 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE (LOOKUP_TYPE = ''APPLICATION'') ORDER BY SEGMENT1', T.USE_YN = 'Y', T.CREATED_BY = 'minyonglee1', T.CREATION_DATE = TO_DATE('20260702232425','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'minyonglee1', T.LAST_UPDATE_DATE = TO_DATE('20260702232425','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('APPLICATION', 'DM', '[B] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''APPLICATION''', 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE (LOOKUP_TYPE = ''APPLICATION'') ORDER BY SEGMENT1', 'Y', 'minyonglee1', TO_DATE('20260702232425','YYYYMMDDHH24MISS'), 'minyonglee1', TO_DATE('20260702232425','YYYYMMDDHH24MISS'));

